import org.jsoup.nodes.*;
import org.jsoup.parser.Parser;
import org.junit.Assert;
import org.junit.Test;

public class CommentExceptionsTest {

    @Test(expected = IndexOutOfBoundsException.class)
    public void asXmlDeclarationXMLisTooShortTest() {
        Comment comment = new Comment("?");
        comment.asXmlDeclaration();
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void asXmlDeclarationXMLisWrongFormatTest() {
        Comment comment = new Comment("!!?");
        comment.asXmlDeclaration();
    }
}

public class CommentTests {

    @Test
    public void constructorTest() {
        Comment comment = new Comment("Test Data");
        Assert.assertEquals("#comment", comment.nodeName());
    }

    @Test
    public void getDataTest() {
        Comment comment = new Comment("Test Data");
        Assert.assertEquals("Test Data", comment.getData());
    }

    @Test
    public void setDataTest() {
        Comment comment = new Comment("Test Data");
        comment.setData("New Test Data");
        Assert.assertEquals("New Test Data", comment.getData());
    }

    @Test
    public void outerHtmlHeadTest() throws IOException {
        Comment comment = new Comment("Test Data");
        StringBuilder sb = new StringBuilder();
        Document.OutputSettings out = new Document.OutputSettings();
        comment.outerHtmlHead(sb, 0, out);
        Assert.assertEquals("<!--Test Data-->", sb.toString());
    }

    @Test
    public void toStringTest() {
        Comment comment = new Comment("Test Data");
        Assert.assertEquals("<!--Test Data-->", comment.toString());
    }

    @Test
    public void cloneTest() {
        Comment comment1 = new Comment("Test Data");
        Comment comment2 = comment1.clone();
        Assert.assertNotSame(comment1, comment2);
        Assert.assertEquals(comment1.toString(), comment2.toString());
    }

    @Test
    public void isXmlDeclarationTest() {
        Comment comment = new Comment("!?");
        Assert.assertTrue(comment.isXmlDeclaration());
    }

    @Test
    public void isXmlDeclarationFalseTest() {
        Comment comment = new Comment("Test Data");
        Assert.assertFalse(comment.isXmlDeclaration());
    }

    @Test
    public void asXmlDeclarationTest() {
        Comment comment = new Comment("!declaration ");
        Assert.assertNotNull(comment.asXmlDeclaration());
    }
}
